import{_ as r,l as n,o as e,c as l,v as t,p as d,x as i,d as p,i as u,S as s}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"Autoencoder 条件因子模型","description":"","frontmatter":{"title":"Autoencoder 条件因子模型","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/autoencoder-factor-model.md","filePath":"quant/autoencoder-factor-model.md","lastUpdated":1789023840000}'),c={name:"quant/autoencoder-factor-model.md"};function A(m,a,h,E,_,b){const o=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="autoencoder-条件因子模型" tabindex="-1">Autoencoder 条件因子模型 <a class="header-anchor" href="#autoencoder-条件因子模型" aria-label="Permalink to &quot;Autoencoder 条件因子模型&quot;">​</a></h1><div class="epigraph"><p>把因子载荷写成公司特征的非线性函数，再用自动编码器从收益里抽取潜因子，条件资产定价模型就不必在线性工具化和无约束 PCA 之间二选一。</p><footer>—— Gu, Kelly and Xiu, Autoencoder Asset Pricing Models, Review of Finance, 2021</footer></div><p><a href="/quant/ipca">IPCA</a> 把载荷写成特征的线性函数，因子仍从收益抽取：\\(\\beta_{it}=\\Gamma^\\top z_{i,t-1}\\)。无约束 PCA 完全不用特征，载荷在样本里自由。<a href="/quant/giglio-xiu">Giglio–Xiu</a> 用 PCA 恢复潜空间再给可观测因子定价，也不把 \\(\\beta\\) 钉在特征上。Gu、Kelly 与 Xiu（2021）的条件自动编码器（conditional autoencoder）走中间路：编码器把 \\(z_{i,t-1}\\) 经多层网络映成 \\(\\beta_{it}\\)，解码端用这些载荷与潜因子去重构收益。非线性允许交互与阈值，同时保留「特征是协方差」的可检验结构。它与 <a href="/quant/gkx-nn3">GKX 的 NN3</a> 不是同一篇文章：2020 年要的是收益预测 \\(R^2\\)，2021 年要的是条件定价模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态因子模型假定 \\(\\beta\\) 不变。公司变大、变贵、加杠杆之后，对共同冲击的敏感度会变；线性 IPCA 用 \\(z\\) 抓住一部分时变，但效应被假定为特征的线性组合。若小盘与高投资的交互才对应某一种风险，线性 \\(\\Gamma\\) 会把交互推进残差，定价误差与协方差拟合一起变差。纯预测网络（NN3）可以拟合 \\(E[r\\mid z]\\)，却不保证这块可预测性来自 \\(\\beta^\\top\\lambda\\)：它可能是误定价，模型在协方差里无法被证伪。</p><p>自动编码器要同时做两件事：用特征生成时变载荷，用收益生成因子，使重构 $ \\beta_{it}^\\top f_t $ 接近 \\(r_{it}\\)。问题是识别与正则。没有对 \\(\\beta\\) 与 \\(f\\) 的尺度约束，网络可以把范数在两端之间挪动；没有时间切分，隐藏层会记住样本内的共同冲击。条件模型的目标函数是定价与协方差，不是交易夏普；把重构误差最小的模型直接拿去排多空，是换了论文的问题。</p><h3 id="条件期望来自载荷-而不是来自另一个预测头" tabindex="-1">条件期望来自载荷，而不是来自另一个预测头 <a class="header-anchor" href="#条件期望来自载荷-而不是来自另一个预测头" aria-label="Permalink to &quot;条件期望来自载荷，而不是来自另一个预测头&quot;">​</a></h3><p>写</p> \\[r_{it}=\\beta(z_{i,t-1};\\theta)^\\top f_t+\\varepsilon_{it}, \\]<p>其中 \\(\\beta(\\cdot;\\theta)\\) 是以特征为输入的网络。条件期望 \\(E[r_{it}\\mid z_{i,t-1}]=\\beta(z_{i,t-1};\\theta)^\\top\\lambda_t\\)（若 \\(E[f_t\\mid z]=\\lambda_t\\) 或进一步参数化）。这把「特征预测收益」限制为「特征预测 \\(\\beta\\)」。若某一特征在预测网络里显著、在载荷网络里对应的行接近零，则该特征的可预测性不能被这 \\(K\\) 个因子吸收——那是误定价候选，或是 \\(K\\) 不够。线性 IPCA 做的是同一检验的线性版；自动编码器只是把 \\(\\beta(\\cdot)\\) 换成非线性。</p><p><span class="marginnote">名称里的 autoencoder 容易让人想起对价格序列做无监督压缩。这里压缩的是截面：用低维 \\(f_t\\) 重构高维 \\(r_t\\)，载荷由 \\(z\\) 工具化。不要把它做成个股收益的序列自编码器后再宣称条件因子模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>估计可用交替或端到端：给定 \\(\\theta\\)（从而给定 \\(\\beta_{it}\\)），\\(f_t\\) 是截面上的加权最小二乘因子；给定 \\(f\\)，\\(\\theta\\) 由重构损失对网络反传。因子个数 \\(K\\) 用样本外定价误差、信息准则或边际解释力选择，与 IPCA 相同。允许一个与特征无关的附加因子，用来捕捉「特征没覆盖的共同冲击」；比较有无该因子的残差，就是在检验工具化是否足够。</p><p>特征 \\(z_{i,t-1}\\) 必须对 \\(t\\) 可测，不能用当期市值去解释当期收益，见<a href="/quant/no-future-function">防止未来函数</a>。规模、账面市值等应使用<a href="/quant/point-in-time">时点</a>口径。训练按时间前向，验证做早停与 \\(K\\)、层宽。评价应同时报告：截面定价误差、协方差拟合、以及把 \\(\\beta^\\top\\hat\\lambda\\) 当作预测分数时相对纯 NN3 的增量。若自动编码器在定价上赢、在纯预测 \\(R^2\\) 上输，说明约束起了作用，不是程序写错。</p> \\[\\min_{\\theta,\\{f_t\\}}\\ \\sum_{i,t}\\bigl(r_{it}-\\beta(z_{i,t-1};\\theta)^\\top f_t\\bigr)^2+\\mathrm{pen}(\\theta). \\]<p>惩罚包括权重衰减与对 \\(\\beta\\) 的平滑；对 \\(f\\) 做正交或方差归一，以免与 \\(\\beta\\) 对偶旋转。旋转不唯一，但 \\(z\\mapsto E[r\\mid z]\\) 在约束下是确定的，与 Giglio–Xiu 强调空间而非旋转的精神一致。</p><h3 id="和-pca、ipca、纯预测网络的对照实验" tabindex="-1">和 PCA、IPCA、纯预测网络的对照实验 <a class="header-anchor" href="#和-pca、ipca、纯预测网络的对照实验" aria-label="Permalink to &quot;和 PCA、IPCA、纯预测网络的对照实验&quot;">​</a></h3><p>对照应预先锁住：无约束 PCA（不用 \\(z\\)）、线性 IPCA、条件自动编码器、GKX 式 NN3。PCA 解释方差可以很好，定价不必好。IPCA 是自动编码器在一层线性、无隐藏单元时的极限。NN3 没有 \\(f_t\\) 这一公共时间因子，个股预测可以各走各的非线性，容易把共同噪声记成特异 alpha。报告一张表：样本内重构、样本外定价、样本外预测 \\(R^2\\)、换手。缺任何一列，都会让「非线性因子模型赢了」无法被读成哪一种赢。</p>',18)),(e(),d(s,null,{default:i(()=>[u(o,{id:"mermaid-48",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E6%BB%9E%E5%90%8E%E7%89%B9%E5%BE%81%20z%22%5D%20--%3E%20ENC%5B%22%E7%BC%96%E7%A0%81%E5%99%A8%20%CE%B2(z)%22%5D%0A%20%20R%5B%22%E6%94%B6%E7%9B%8A%E9%9D%A2%E6%9D%BF%22%5D%20--%3E%20FAC%5B%22%E6%8A%BD%E5%8F%96%E6%BD%9C%E5%9B%A0%E5%AD%90%20f%22%5D%0A%20%20ENC%20--%3E%20REC%5B%22%E9%87%8D%E6%9E%84%20%CE%B2%E1%B5%80%20f%22%5D%0A%20%20FAC%20--%3E%20REC%0A%20%20REC%20--%3E%20ERR%5B%22%E5%AE%9A%E4%BB%B7%E8%AF%AF%E5%B7%AE%20%2F%20%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20ERR%20--%3E%20OOS%5B%22%E6%A0%B7%E6%9C%AC%E5%A4%96%E5%AF%B9%E7%85%A7%3A%20PCA%20%2F%20IPCA%20%2F%20NN3%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>自动编码器的正则来自瓶颈 \\(K\\)：共同时间变化只允许 \\(K\\) 维，迫使网络把特征用到「能解释共同收益」的方向上。非线性的价值是交互：例如高投资只在小盘上对应更高的某因子载荷。若真实世界近似线性，隐藏层会被早停掐掉，模型退回 IPCA——这是优点。若非线性只存在于样本内的几次危机，测试年会露出定价误差，模型应被判为过拟合而不是「深度因子」。</p><p>与纯 PCA 的差别在于特征对 \\(\\beta\\) 的约束降低了个股载荷的噪声：个股时间序列回归的 \\(\\beta\\) 极吵，IPCA / 自动编码器借用截面上相似 \\(z\\) 的公司来稳 \\(\\beta\\)。这与收缩是同一几何。代价是：与所有可观测特征都无关的共同风险被推进残差；若检验资产恰好被这块风险定价，模型会显示系统性误定价。无约束因子的对照就是为这一代价准备的。</p><p><span class="marginnote">条件模型的 \\(\\lambda\\) 仍可以时变。β 与 λ 的协方差会进入无条件均值，与条件 CAPM 相同。只报无条件 α 而不报条件定价误差，会把时变风险错写成 alpha。</span></p><h3 id="不要把重构当交易引擎" tabindex="-1">不要把重构当交易引擎 <a class="header-anchor" href="#不要把重构当交易引擎" aria-label="Permalink to &quot;不要把重构当交易引擎&quot;">​</a></h3><p>训练损失是重构平方误差，对极端收益敏感，也未必对齐排序交易。若最终要交易，应在验证集上用截面 IC 或扣费 IR 做早停，并承认这时你已经离开了 2021 年论文的目标函数，更接近 2020 年的预测论文。两者可以共享特征表，不能共享「赢」的定义。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要用五因子自己的构造组合去训练自动编码器再给五因子定价——空间被自己张成。不要把隐藏单元解释成宏观因子名字；旋转仍不唯一。A 股特征质量与涨跌停使 \\(\\beta(z)\\) 的输入分布有跳，滚动重估比全样本一次编码更重要。计算上，每月截面 \\(N\\) 大时可用特征加权的因子提取，但加权方案必须在验证前锁定。</p><p><span class="marginnote">出处：Gu, Kelly and Xiu, <em>Review of Finance</em>, 2021；Kelly, Pruitt and Su, <em>JFE</em>, 2019（IPCA）；Gu, Kelly and Xiu, <em>RFS</em>, 2020（预测对照）；Giglio and Xiu, <em>JPE</em>, 2021（漏因子与潜空间）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>条件自动编码器把 IPCA 的线性 \\(\\beta(z)\\) 换成网络，潜因子仍从收益抽取，目标是条件定价而非纯预测。</li><li>识别靠瓶颈 \\(K\\) 与特征时点；旋转不唯一，条件期望在约束下确定。</li><li>对照必须包括 PCA、线性 IPCA 与 NN3，分别看方差、定价与预测。</li><li>重构损失不等于可交易 IR；换目标函数要显式声明。</li><li>出处：Gu–Kelly–Xiu, <em>Review of Finance</em>, 2021；Kelly–Pruitt–Su, <em>JFE</em>, 2019；Gu–Kelly–Xiu, <em>RFS</em>, 2020。</li></ul>',11))])}const P=r(c,[["render",A]]);export{C as __pageData,P as default};
